function firstIndexOf(haystack: string, needle: string): number {
  const n = haystack.length, m = needle.length;
  for (let start = 0; start + m <= n; start++) {
    let j = 0;
    while (j < m && haystack[start + j] === needle[j]) j++;
    if (j === m) return start;
  }
  return -1;
}

